changeSet.sql:
if exists(select * from INFORMATION_SCHEMA.TABLES where TABLE_SCHEMA = 'dbo' and TABLE_NAME = 'GenericCommand')
begin 
	exec sp_rename 'dbo.GenericCommand', 'GenericCommand_backup';
end

changeSet.rollback:
if exists(select * from INFORMATION_SCHEMA.TABLES where TABLE_SCHEMA = 'dbo' and TABLE_NAME = 'GenericCommand_backup')
begin 
	exec sp_rename 'dbo.GenericCommand_backup', 'GenericCommand';
end
